// packages/validation/dist/hard-output-rules/rules/senior-quality-rules.js
function checkNoMagicNumbers(content, sectionType) {
  const violations = [];
  const codeBlocks = extractCodeBlocks(content);
  const magicNumberPattern = /(?:(?:timeout|delay|limit|max|min|size|count|threshold|retry|interval|duration|width|height|margin|padding)\s*[:=]\s*)\d{2,}/gi;
  for (const codeBlock of codeBlocks) {
    const matches = codeBlock.match(magicNumberPattern);
    if (matches && matches.length >= 3) {
      violations.push(makeViolation("no_magic_numbers", sectionType, "Code examples contain multiple raw numeric literals \u2014 extract to named constants (e.g., MAX_RETRY_COUNT, DEFAULT_TIMEOUT_MS) for maintainability.", `Found ${matches.length} magic numbers in code block`));
    }
  }
  const hasConstantGuidance = matchesAny(content, ["namedConstantSignals"]);
  if (!hasConstantGuidance && codeBlocks.length > 0) {
    violations.push(makeViolation("no_magic_numbers", sectionType, "Technical spec should mandate named constants \u2014 all configuration values, thresholds, and limits must be extracted to named constants, not raw literals."));
  }
  return violations;
}
function checkDefensiveCoding(content, sectionType) {
  return findAbsenceViolation(content, phrases("defensiveCodingSignals"), 2, "defensive_coding", sectionType, "Technical spec must enforce defensive coding \u2014 guard clauses, preconditions, null safety, bounds checking at all entry points. Fail fast on invalid state.");
}
function checkMethodSizeLimits(content, sectionType) {
  const violations = [];
  const codeBlocks = extractCodeBlocks(content);
  const funcPattern = /(?:func |function |def |fn |fun |public |private |protected |internal |static )*(?:func|function|def|fn|fun|method)\s+(\w+)/;
  for (const codeBlock of codeBlocks) {
    const lines = codeBlock.split("\n");
    let currentFuncName = null;
    let funcStartLine = 0;
    let braceDepth = 0;
    let inFunction = false;
    for (let index2 = 0; index2 < lines.length; index2++) {
      const line = lines[index2];
      if (!inFunction) {
        const match = line.match(funcPattern);
        if (match) {
          currentFuncName = match[1] ?? "anonymous";
          funcStartLine = index2;
          inFunction = true;
          braceDepth = 0;
        }
      }
      if (inFunction) {
        braceDepth += (line.match(/\{/g) || []).length;
        braceDepth -= (line.match(/\}/g) || []).length;
        if (braceDepth <= 0 && line.includes("}")) {
          const funcLineCount = index2 - funcStartLine + 1;
          if (funcLineCount > 30) {
            violations.push(makeViolation("method_size_limits", sectionType, `Code example shows function '${currentFuncName}' spanning ${funcLineCount} lines \u2014 extract logic into smaller functions. Methods should be ~30 lines max in PRD examples.`, currentFuncName));
          }
          inFunction = false;
          currentFuncName = null;
        }
      }
    }
  }
  return violations;
}
