// packages/validation/dist/hard-output-rules/rules/testing-rules.js
function checkMandatoryTestCoverage(content, sectionType) {
  const lowered = content.toLowerCase();
  const unitSignals = [
    "unit test",
    "ut-",
    "unit coverage",
    "function test",
    "method test",
    "class test",
    "module test"
  ];
  const integrationSignals = [
    "integration test",
    "it-",
    "api test",
    "contract test",
    "component test",
    "service test",
    "end-to-end",
    "e2e"
  ];
  const coverageSignals = [
    "test coverage",
    "code coverage",
    "coverage target",
    "coverage threshold",
    "coverage report",
    "line coverage",
    "branch coverage",
    "100% coverage",
    "minimum coverage"
  ];
  const hasUnit = unitSignals.some((s) => lowered.includes(s));
  const hasIntegration = integrationSignals.some((s) => lowered.includes(s));
  const hasCoverage = coverageSignals.some((s) => lowered.includes(s));
  const violations = [];
  if (!hasUnit || !hasIntegration) {
    violations.push(makeViolation("mandatory_test_coverage", sectionType, "Test spec must include both unit tests and integration tests \u2014 every public method/endpoint needs corresponding test specifications."));
  }
  if (!hasCoverage) {
    violations.push(makeViolation("mandatory_test_coverage", sectionType, "Test spec must define coverage targets \u2014 specify minimum code coverage thresholds for unit, integration, and overall coverage."));
  }
  return violations;
}
